import json,urllib.request,datetime
base='http://127.0.0.1:17448'
def get(path):
 try:
  with urllib.request.urlopen(base+path,timeout=6) as r:
   obj=json.load(r)
  return obj
 except Exception as e:
  return {'probe_error':type(e).__name__+': '+str(e)[:120]}
h=get('/health')
cs=get('/api/supervisor-watchdog/managed-chats')
ass=get('/api/supervisor-watchdog/agent-assignments')
out={'time':datetime.datetime.now().isoformat(),'health':{k:h.get(k) for k in ('status','ok','version','uptime','probe_error') if k in h},'chats':[{k:v.get(k) for k in ('name','status','error','highMode','generating','openTabs','lastSeenAt')} for v in cs.get('chats',[])],'bridge_assignments':[{k:v.get(k) for k in ('id','state','dispatchCount','lastDiagnostic','lastPreflightReason','currentHead','ciConclusion')} for v in ass.get('assignments',[]) if 'bridge' in str(v.get('targetChatId','')).lower() or v.get('targetChatId')=='chat-6ac45836-87a0-83ed-bea4-0ad0f99c8982'],'query_errors':{k:x.get('probe_error') for k,x in [('chats',cs),('assignments',ass)] if x.get('probe_error')}}
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
